{
  "avaliacoes": [
    {
      "id": "E3be00994b6f7bf11",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "Gargalo na instalação é descrito como um ponto de capacidade limitada por onde o fluxo precisa passar para alcançar os compradores finais; quando essa limitação existe, surgem decisões de priorização de entregas, alocação de capacidade e eventual necessidade de expansão para aliviar a restrição.",
          "trechos": [
            "E3be00994b6f7bf11:699:1393",
            "E3be00994b6f7bf11:1393:2086"
          ],
          "condicoes": [
            "aplica-se a redes ou sistemas em que todo o produto ou serviço passa por um ponto comum"
          ],
          "limites": [
            "fonte de caráter glossarial, sem método de quantificação de perdas, sem atribuição causal específica para FPSO",
            "exemplo dado é genérico e inclui sistemas como eletricidade, não uma instalação offshore específica"
          ]
        }
      ]
    },
    {
      "id": "E664cd6a9df3ed400",
      "pertinente": true,
      "tipo": "recomendacao",
      "achados": [
        {
          "proposicao": "O trabalho propõe um modelo de gestão da água produzida em campos onshore baseado em árvore de decisões, analisando operações, movimentação, origem e destino da água e definindo prioridades ambientais.",
          "trechos": [
            "E664cd6a9df3ed400:0:699",
            "E664cd6a9df3ed400:699:1393"
          ],
          "condicoes": [
            "voltado a campos onshore de petróleo e gás natural no Brasil",
            "baseado em revisão bibliográfica e entrevistas segundo o próprio trecho"
          ],
          "limites": [
            "não trata diretamente de FPSO/FSO",
            "não apresenta perdas de produção, balanços produtivos ou causas de restrição operacional no trecho fornecido"
          ]
        },
        {
          "proposicao": "O texto associa 'gargalos' a desafios críticos no gerenciamento de água e define como objetivo específico descrever etapas da gestão da água produzida relacionando atividades, técnicas e tecnologias existentes.",
          "trechos": [
            "E664cd6a9df3ed400:0:699",
            "E664cd6a9df3ed400:2093:2382"
          ],
          "condicoes": [
            "recorte centrado em gerenciamento de água produzida"
          ],
          "limites": [
            "utilidade indireta para perdas e restrições de produção, pois o nexo operacional com perda produtiva não é explicitado nesses trechos"
          ]
        }
      ]
    },
    {
      "id": "E5b11efc7c3cf28ff",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "Em unidades marítimas, a água produzida pode ser reinjetada para auxiliar a produção de óleo ou tratada para descarte no mar conforme exigências legais, indicando dois destinos operacionais relevantes no balanço de produção.",
          "trechos": [
            "E5b11efc7c3cf28ff:0:699"
          ],
          "condicoes": [
            "aplica-se ao contexto de produção marítima de óleo e gás"
          ],
          "limites": [
            "o trecho não informa critérios de seleção entre reinjeção e descarte",
            "não quantifica impacto dessas rotas em perdas de produção"
          ]
        },
        {
          "proposicao": "As facilidades de produção de unidades marítimas são descritas como instalações destinadas a realizar, sob condições controladas, o processamento primário dos fluidos, o que conecta restrições de processo à capacidade produtiva da unidade.",
          "trechos": [
            "E5b11efc7c3cf28ff:0:699",
            "E5b11efc7c3cf28ff:699:1397"
          ],
          "condicoes": [
            "referido ao processamento primário em unidades marítimas"
          ],
          "limites": [
            "não discrimina quais subsistemas limitam produção nem como medir perdas planejadas ou não planejadas"
          ]
        },
        {
          "proposicao": "No pré-sal, alta pressão e presença frequente de CO2 e H2S são apontadas como características que aumentam a complexidade da exploração e produção, podendo atuar como condicionantes técnicos de restrições e desempenho.",
          "trechos": [
            "E5b11efc7c3cf28ff:699:1397"
          ],
          "condicoes": [
            "muitas vezes associado ao óleo da camada pré-sal, segundo o trecho"
          ],
          "limites": [
            "o texto não demonstra causalmente perdas de produção específicas decorrentes desses contaminantes",
            "não fornece parâmetros operacionais ou limites"
          ]
        }
      ]
    },
    {
      "id": "E78483ced0137641e",
      "pertinente": true,
      "tipo": "norma",
      "achados": [
        {
          "proposicao": "Falhas no autodiagnóstico e na implementação de ações contingenciais e medidas corretivas, em prazos compatíveis com o risco, são apontadas como fatores que levaram à interdição de instalações, com consequente perda de produção e receita.",
          "trechos": [
            "E78483ced0137641e:0:699"
          ],
          "condicoes": [
            "contexto de auditoria temática da ANP",
            "casos citados de operadores e instalações específicas"
          ],
          "limites": [
            "exemplos de casos concretos; não devem ser generalizados como regra universal de causalidade",
            "o trecho não detalha tecnicamente todas as barreiras falhas nem apresenta metodologia de cálculo das perdas"
          ]
        },
        {
          "proposicao": "A nota técnica explicita que interdições de unidades podem gerar perdas econômicas muito elevadas e que a magnitude cresce com o volume de produção da instalação.",
          "trechos": [
            "E78483ced0137641e:0:699",
            "E78483ced0137641e:699:1395"
          ],
          "condicoes": [
            "estimativas aplicadas a exemplos mencionados na nota"
          ],
          "limites": [
            "valores econômicos apresentados são estimativas e dependem do caso",
            "o foco é consequência econômica, não balanço completo de produção potencial versus realizada"
          ]
        },
        {
          "proposicao": "A nota define barreira como mecanismo físico ou procedimento administrativo para impedir ou mitigar acidentes, e funcionalidade da barreira como capacidade de cumprir a função conforme projetada, incluindo confiabilidade e premissas das análises de risco; isso fornece base para atribuir causas de perda por indisponibilidade ou degradação de barreiras.",
          "trechos": [
            "E78483ced0137641e:1395:2088",
            "E78483ced0137641e:2088:2447"
          ],
          "condicoes": [
            "no âmbito do SGSO e das análises e estudos de risco da unidade"
          ],
          "limites": [
            "conceitua segurança operacional, não um KPI produtivo específico",
            "não estabelece, nos trechos apresentados, fórmula de conversão entre falha de barreira e perda produtiva"
          ]
        }
      ]
    },
    {
      "id": "E813ca985a9541b76",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "O gerenciamento da água produzida é apresentado como tema técnico, ambiental e regulatório passível de avaliação por modelo decisório e indicador de qualidade do gerenciamento, o que sugere um eixo de controle operacional associado ao desempenho.",
          "trechos": [
            "E813ca985a9541b76:0:699",
            "E813ca985a9541b76:699:1398"
          ],
          "condicoes": [
            "aplicado a operações de produção de petróleo e gás no contexto do estudo"
          ],
          "limites": [
            "não trata especificamente de FPSO/FSO nos trechos fornecidos",
            "o indicador é apenas proposto, sem detalhamento metodológico no excerto"
          ]
        },
        {
          "proposicao": "O estudo justifica o tema pelo elevado volume de água produzida e pela expectativa de aumento com o amadurecimento de campos ou poços, indicando que a evolução do corte de água pode pressionar operações e gestão.",
          "trechos": [
            "E813ca985a9541b76:699:1398",
            "E813ca985a9541b76:1398:2098"
          ],
          "condicoes": [
            "associado ao amadurecimento de campos ou poços"
          ],
          "limites": [
            "números relevantes estão apagados",
            "o trecho não afirma diretamente que esse aumento cause perda de produção, apenas caracteriza a problemática"
          ]
        }
      ]
    },
    {
      "id": "E81054901bc76918c",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "Campos maduros são caracterizados por entrada em declínio natural após o pico de produção, o que é diretamente pertinente à diferença entre produção potencial histórica e produção corrente.",
          "trechos": [
            "E81054901bc76918c:0:695",
            "E81054901bc76918c:695:1394"
          ],
          "condicoes": [
            "aplica-se a campos que já atingiram o pico de produção"
          ],
          "limites": [
            "trata do campo e não necessariamente da unidade FPSO isoladamente",
            "não separa perda planejada, não planejada e declínio natural"
          ]
        },
        {
          "proposicao": "Na fase madura, são requeridos estudos e investimentos adequados para evitar ou minimizar perda de produção e aumento de custos, relacionando gestão técnica a desempenho econômico.",
          "trechos": [
            "E81054901bc76918c:695:1394"
          ],
          "condicoes": [
            "durante a fase de declínio de campos maduros"
          ],
          "limites": [
            "enunciado geral, sem detalhar quais ações, indicadores ou critérios de seleção"
          ]
        },
        {
          "proposicao": "O caso do campo de Marlim é apresentado com projetos de desenvolvimento complementar voltados à antecipação da produção e à redução da fração de água produzida, sugerindo duas alavancas operacionais para mitigar restrições de desempenho em campo maduro.",
          "trechos": [
            "E81054901bc76918c:0:695"
          ],
          "condicoes": [
            "referente ao estudo de caso citado no trecho"
          ],
          "limites": [
            "não há comprovação empírica de resultados nos trechos fornecidos",
            "não informa como essas iniciativas impactaram efetivamente as perdas"
          ]
        }
      ]
    }
  ],
